"""Catálogo de skills e seleção híbrida.

Skills são arquivos markdown com front-matter YAML em `skills/`. Nenhuma regra comercial
vive em `.py`. O catálogo (`menu`) é montado só do front-matter e fica sempre no contexto;
os corpos entram apenas quando selecionados.

Seleção híbrida:
- `always_on` e `event_triggered` são decididas por CÓDIGO — o modelo não tem voto. Se o
  breaker está aberto, `quote_failure` entra, independentemente da intenção detectada.
- `model_selected` é escolhida pelo modelo (ou pelo roteador de fallback) pela intenção.
"""

from __future__ import annotations

import re
from collections.abc import Iterable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Literal

import yaml

from agent.rules import rule_ids

Activation = Literal["always_on", "model_selected", "event_triggered"]
ACTIVATIONS: tuple[str, ...] = ("always_on", "model_selected", "event_triggered")
KNOWN_EVENTS: frozenset[str] = frozenset(
    {"quote_retries_exhausted", "breaker_open", "quote_refused", "handoff_required"}
)

_FRONT_MATTER_RE = re.compile(r"\A---\s*\n(.*?)\n---\s*\n?(.*)\Z", re.DOTALL)


class SkillConfigError(ValueError):
    pass


@dataclass(frozen=True)
class Skill:
    id: str
    name: str
    activation: Activation
    when_to_use: str
    body: str
    path: str
    triggers: tuple[str, ...] = ()
    excludes: tuple[str, ...] = ()
    rules: tuple[str, ...] = ()
    priority: int = 100
    fallback_template: str | None = None

    def menu_line(self) -> str:
        return f"- `{self.id}`: {self.when_to_use}"

    def render(self) -> str:
        return f"### Skill `{self.id}` — {self.name}\n{self.body.strip()}\n"


@dataclass
class Selection:
    skills: list[Skill]
    selected_by: dict[str, str] = field(default_factory=dict)
    excluded: list[str] = field(default_factory=list)
    events: list[str] = field(default_factory=list)

    @property
    def ids(self) -> list[str]:
        return [s.id for s in self.skills]

    @property
    def rules(self) -> list[str]:
        seen: list[str] = []
        for s in self.skills:
            for r in s.rules:
                if r not in seen:
                    seen.append(r)
        return seen

    def render_bodies(self) -> str:
        return "\n".join(s.render() for s in self.skills)


def parse_skill_file(path: Path, valid_rules: frozenset[str]) -> Skill:
    text = path.read_text(encoding="utf-8")
    match = _FRONT_MATTER_RE.match(text)
    if not match:
        raise SkillConfigError(f"{path}: front-matter YAML ausente (bloco entre '---')")
    try:
        meta: dict[str, Any] = yaml.safe_load(match.group(1)) or {}
    except yaml.YAMLError as exc:
        raise SkillConfigError(f"{path}: front-matter inválido: {exc}") from exc
    body = match.group(2)

    for key in ("id", "name", "activation", "when_to_use"):
        if not meta.get(key):
            raise SkillConfigError(f"{path}: campo obrigatório '{key}' ausente")
    if meta["activation"] not in ACTIVATIONS:
        raise SkillConfigError(
            f"{path}: activation '{meta['activation']}' inválida; use {ACTIVATIONS}"
        )
    if str(meta["id"]) != path.stem:
        raise SkillConfigError(f"{path}: id '{meta['id']}' difere do nome do arquivo")

    triggers = tuple(str(t) for t in (meta.get("triggers") or []))
    if meta["activation"] == "event_triggered" and not triggers:
        raise SkillConfigError(f"{path}: skill event_triggered precisa de 'triggers'")
    unknown_events = set(triggers) - KNOWN_EVENTS
    if unknown_events:
        raise SkillConfigError(f"{path}: triggers desconhecidos {sorted(unknown_events)}")

    rules = tuple(str(r) for r in (meta.get("rules") or []))
    unknown_rules = set(rules) - valid_rules
    if unknown_rules:
        raise SkillConfigError(f"{path}: rules desconhecidas {sorted(unknown_rules)}")

    if not body.strip():
        raise SkillConfigError(f"{path}: corpo vazio")

    return Skill(
        id=str(meta["id"]),
        name=str(meta["name"]),
        activation=meta["activation"],
        when_to_use=str(meta["when_to_use"]).strip(),
        body=body,
        path=str(path),
        triggers=triggers,
        excludes=tuple(str(x) for x in (meta.get("excludes") or [])),
        rules=rules,
        priority=int(meta.get("priority", 100)),
        fallback_template=(
            str(meta["fallback_template"]).strip() if meta.get("fallback_template") else None
        ),
    )


class SkillCatalog:
    def __init__(self, skills: Iterable[Skill]):
        self._skills: dict[str, Skill] = {}
        for skill in skills:
            if skill.id in self._skills:
                raise SkillConfigError(f"skill duplicada: {skill.id}")
            self._skills[skill.id] = skill
        for skill in self._skills.values():
            for other in skill.excludes:
                if other not in self._skills:
                    raise SkillConfigError(f"{skill.path}: excludes referencia '{other}' inexistente")

    @classmethod
    def load(cls, directory: Path | str = "skills") -> SkillCatalog:
        directory = Path(directory)
        rules_path = directory / "business_rules.yaml"
        valid_rules = rule_ids(rules_path) if rules_path.exists() else rule_ids()
        files = sorted(directory.glob("*.md"))
        if not files:
            raise SkillConfigError(f"nenhuma skill (*.md) em {directory}")
        return cls(parse_skill_file(p, valid_rules) for p in files)

    # ------------------------------------------------------------------ consulta
    def __len__(self) -> int:
        return len(self._skills)

    def ids(self) -> list[str]:
        return list(self._skills)

    def get(self, skill_id: str) -> Skill:
        return self._skills[skill_id]

    def all(self) -> list[Skill]:
        return list(self._skills.values())

    def model_selectable_ids(self) -> list[str]:
        return [s.id for s in self._skills.values() if s.activation == "model_selected"]

    def menu(self) -> str:
        """`available_skills`: só front-matter, nenhum corpo."""
        lines = [s.menu_line() for s in sorted(self._skills.values(), key=lambda s: s.id)]
        return "\n".join(lines)

    # ------------------------------------------------------------------ seleção
    def select(self, events: Iterable[str] = (), model_choice: Iterable[str] = ()) -> Selection:
        events_set = set(events)
        choice = [c for c in model_choice if c in self._skills]
        selected_by: dict[str, str] = {}

        for skill in self._skills.values():
            if skill.activation == "always_on":
                selected_by[skill.id] = "always_on"
            elif skill.activation == "event_triggered" and events_set.intersection(skill.triggers):
                selected_by[skill.id] = "event"
        for skill_id in choice:
            skill = self._skills[skill_id]
            if skill.activation == "model_selected" and skill_id not in selected_by:
                selected_by[skill_id] = "model"

        # Exclusões só valem vindas de skills decididas por código: o modelo não desliga
        # uma skill de evento escolhendo outra.
        excluded: list[str] = []
        for skill_id, by in list(selected_by.items()):
            if by in ("always_on", "event"):
                for other in self._skills[skill_id].excludes:
                    if other in selected_by and selected_by[other] == "model":
                        excluded.append(other)
        for other in excluded:
            selected_by.pop(other, None)

        skills = sorted(
            (self._skills[i] for i in selected_by), key=lambda s: (-s.priority, s.id)
        )
        return Selection(skills, selected_by, excluded, sorted(events_set))
EOF

cat > tests/test_skills.py <<'EOF'
import re
from pathlib import Path

import pytest

from agent.rules import load_rules
from agent.skills import SkillCatalog, SkillConfigError, parse_skill_file

SKILLS_DIR = Path(__file__).resolve().parents[1] / "skills"


@pytest.fixture(scope="module")
def catalog() -> SkillCatalog:
    return SkillCatalog.load(SKILLS_DIR)


def test_catalogo_tem_as_oito_skills(catalog):
    assert set(catalog.ids()) == {
        "identity_and_scope", "quote", "quote_failure", "underwriting_refusal",
        "objection_handling", "coverage_explanation", "handoff", "out_of_scope",
    }


def test_menu_so_usa_front_matter(catalog):
    menu = catalog.menu()
    for skill in catalog.all():
        assert skill.id in menu and skill.when_to_use in menu
        # nenhuma linha do corpo aparece no menu
        first_body_line = next(ln for ln in skill.body.strip().splitlines() if ln.strip())
        assert first_body_line.strip() not in menu
    assert len(menu) < 2500


def test_so_corpos_selecionados_entram(catalog):
    sel = catalog.select(events=(), model_choice=["quote"])
    text = sel.render_bodies()
    assert "Skill `quote`" in text and "Skill `identity_and_scope`" in text
    assert "Skill `objection_handling`" not in text
    assert "Skill `handoff`" not in text


def test_breaker_open_forca_quote_failure_mesmo_com_modelo_escolhendo_quote(catalog):
    sel = catalog.select(events={"breaker_open"}, model_choice=["quote"])
    assert "quote_failure" in sel.ids
    assert "quote" not in sel.ids and sel.excluded == ["quote"]
    assert sel.selected_by["quote_failure"] == "event"


def test_recusa_ativa_underwriting_refusal_e_remove_quote(catalog):
    sel = catalog.select(events={"quote_refused"}, model_choice=["quote", "objection_handling"])
    assert "underwriting_refusal" in sel.ids and "quote" not in sel.ids
    assert "objection_handling" in sel.ids


def test_handoff_exclui_skills_de_venda(catalog):
    sel = catalog.select(events={"handoff_required"}, model_choice=["quote", "objection_handling"])
    assert sel.ids[:2] == ["identity_and_scope", "handoff"]
    assert set(sel.excluded) == {"quote", "objection_handling"}


def test_modelo_nao_consegue_ativar_skill_de_evento(catalog):
    sel = catalog.select(events=(), model_choice=["handoff", "quote_failure", "quote"])
    assert "handoff" not in sel.ids and "quote_failure" not in sel.ids and "quote" in sel.ids


def test_regras_referenciadas_existem(catalog):
    rules = load_rules(SKILLS_DIR / "business_rules.yaml")
    assert set(rules) == {f"BR-{i:02d}" for i in range(1, 15)}
    for skill in catalog.all():
        assert skill.rules and set(skill.rules) <= set(rules)


def test_skills_de_evento_tem_template_de_fallback(catalog):
    for sid in ("quote_failure", "underwriting_refusal", "handoff", "out_of_scope"):
        assert catalog.get(sid).fallback_template


def test_nova_skill_aparece_sem_tocar_em_python(tmp_path):
    for p in SKILLS_DIR.glob("*"):
        (tmp_path / p.name).write_text(p.read_text(encoding="utf-8"), encoding="utf-8")
    (tmp_path / "renovacao.md").write_text(
        "---\nid: renovacao\nname: Renovação\nactivation: model_selected\n"
        "when_to_use: \"O lead quer renovar.\"\nrules: [BR-01]\n---\n## Corpo\nfaça x\n",
        encoding="utf-8",
    )
    cat = SkillCatalog.load(tmp_path)
    assert "renovacao" in cat.ids() and "`renovacao`" in cat.menu()


@pytest.mark.parametrize("content,msg", [
    ("## sem front matter\n", "front-matter"),
    ("---\nid: x\nname: X\nactivation: sempre\nwhen_to_use: y\n---\ncorpo\n", "activation"),
    ("---\nid: x\nname: X\nactivation: event_triggered\nwhen_to_use: y\n---\ncorpo\n", "triggers"),
    ("---\nid: x\nname: X\nactivation: model_selected\nwhen_to_use: y\nrules: [BR-99]\n---\ncorpo\n", "rules"),
    ("---\nid: y\nname: X\nactivation: model_selected\nwhen_to_use: y\n---\ncorpo\n", "difere"),
    ("---\nid: x\nname: X\nactivation: model_selected\nwhen_to_use: y\n---\n", "vazio"),
])
def test_front_matter_invalido_falha_no_boot_com_mensagem_clara(tmp_path, content, msg):
    p = tmp_path / "x.md"
    p.write_text(content, encoding="utf-8")
    with pytest.raises(SkillConfigError, match=msg):
        parse_skill_file(p, frozenset({"BR-01"}))


def test_nenhuma_regra_comercial_em_python():
