3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { describeError, getTrace } from "../api";
5	import type { BreakerSnapshot, TraceEvent } from "../types";
6	import { BreakerPill } from "./BreakerPill";
7	import { TraceEventRow } from "./TraceEventRow";
8	
9	const POLL_MS = 1500;
10	
11	interface TracePanelProps {
12	  conversationId: string | null;
13	  // Incrementado pela página após cada resposta para forçar refresh imediato.
14	  refreshToken: number;
15	  breaker: BreakerSnapshot | null;
16	}
17	
18	interface TurnGroup {
19	  turn: number | null;
20	  events: { key: string; event: TraceEvent }[];
21	}
22	
23	function groupByTurn(events: TraceEvent[]): TurnGroup[] {
24	  const groups = new Map<number | null, TurnGroup>();
25	  events.forEach((ev, idx) => {
26	    const turn = typeof ev.turn === "number" ? ev.turn : null;
27	    let g = groups.get(turn);
28	    if (!g) {
29	      g = { turn, events: [] };
30	      groups.set(turn, g);
31	    }
32	    g.events.push({ key: ev.span_id ?? `${turn ?? "x"}-${idx}`, event: ev });
33	  });
34	  return [...groups.values()];
35	}
36	
37	function toJsonl(events: TraceEvent[]): string {
38	  return events.map((ev) => JSON.stringify(ev)).join("\n") + (events.length ? "\n" : "");
39	}
40	
41	export function TracePanel({ conversationId, refreshToken, breaker }: TracePanelProps) {
42	  const [events, setEvents] = useState<TraceEvent[]>([]);
43	  const [error, setError] = useState<string | null>(null);
44	  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
45	  const inFlight = useRef<AbortController | null>(null);
46	
47	  const load = useCallback(async (): Promise<TraceEvent[] | null> => {
48	    if (!conversationId) return null;
49	    inFlight.current?.abort();
50	    const ctrl = new AbortController();
51	    inFlight.current = ctrl;
52	    try {
53	      const res = await getTrace(conversationId, ctrl.signal);
54	      if (ctrl.signal.aborted) return null;
55	      setEvents(res.events);
56	      setError(null);
57	      return res.events;
58	    } catch (err) {
59	      if (ctrl.signal.aborted) return null;
60	      setError(describeError(err));
61	      return null;
62	    }
63	  }, [conversationId]);
64	
65	  // Polling enquanto houver conversa; limpa ao trocar/encerrar.
66	  useEffect(() => {
67	    if (!conversationId) {
68	      setEvents([]);
69	      setError(null);
70	      return;
71	    }
72	    setEvents([]);
73	    setExpanded(new Set());
74	    void load();
75	    const id = window.setInterval(() => void load(), POLL_MS);
76	    return () => {
77	      window.clearInterval(id);
78	      inFlight.current?.abort();
79	    };
80	  }, [conversationId, load]);
81	
82	  useEffect(() => {
83	    if (refreshToken > 0) void load();
84	  }, [refreshToken, load]);
85	
86	  function toggle(key: string) {
87	    setExpanded((prev) => {
88	      const next = new Set(prev);
89	      if (next.has(key)) next.delete(key);
90	      else next.add(key);
91	      return next;
92	    });
93	  }
94	
95	  // Busca a versão mais recente antes de exportar para não perder evento.
96	  async function exportJsonl() {
97	    if (!conversationId) return;
98	    const latest = (await load()) ?? events;
99	    const blob = new Blob([toJsonl(latest)], { type: "application/x-ndjson" });
100	    const url = URL.createObjectURL(blob);
101	    const a = document.createElement("a");
102	    a.href = url;
103	    a.download = `trace-${conversationId}.jsonl`;
104	    document.body.appendChild(a);
105	    a.click();
106	    a.remove();
107	    URL.revokeObjectURL(url);
108	  }
109	
110	  const groups = groupByTurn(events);
111	
112	  return (
113	    <aside className="panel trace" aria-label="Trace da conversa">
114	      <div className="trace-header">
115	        <h2>
116	          Trace <code className="mono">{conversationId ?? "—"}</code>
117	        </h2>
118	        <span className="trace-count">{events.length} eventos</span>
119	      </div>
120	
121	      {error && (
122	        <p className="trace-error" role="status">
123	          trace indisponível: {error} — tentando novamente…
124	        </p>
125	      )}
126	
127	      <div className="trace-body">
128	        {!conversationId && <p className="trace-empty">Sem conversa ativa.</p>}
129	        {conversationId && events.length === 0 && !error && (
130	          <p className="trace-empty">Nenhum evento ainda.</p>
131	        )}
132	        {groups.map((g) => (
133	          <section key={g.turn ?? "none"} className="trace-turn">
134	            <h3 className="trace-turn-title">
135	              {g.turn === null ? "Sem turno" : `Turno ${g.turn}`}
136	            </h3>
137	            <ul className="trace-list">
138	              {g.events.map(({ key, event }) => (
139	                <TraceEventRow
140	                  key={key}
141	                  event={event}
142	                  expanded={expanded.has(key)}
143	                  onToggle={() => toggle(key)}
144	                />
145	              ))}
146	            </ul>
147	          </section>
148	        ))}
149	      </div>
150	
151	      <footer className="trace-footer">
152	        <div className="trace-footer-row">
153	          <BreakerPill breaker={breaker} />
154	          <button
155	            type="button"
156	            className="btn"
157	            onClick={() => void exportJsonl()}
158	            disabled={!conversationId || events.length === 0}
159	            aria-label="Exportar trace em JSON Lines"
160	          >
161	            Exportar trace (.jsonl)
162	          </button>
163	        </div>
164	        <ul className="legend" aria-label="Legenda dos ícones">
165	          <li><span className="trace-icon trace-icon-ok">✓</span> ok / pass</li>
166	          <li><span className="trace-icon trace-icon-error">✗</span> error / blocked</li>
167	          <li><span className="trace-icon trace-icon-retry">↻</span> retry / skipped</li>
168	          <li><span className="trace-icon trace-icon-warn">⚠</span> refused / degraded</li>
169	        </ul>
170	      </footer>
171	    </aside>
172	  );
173	}
