1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { describeError, sendMessage } from "../api";
5	import type { ChatMessage, MessageReply } from "../types";
6	import { Composer } from "./Composer";
7	import { MessageBubble } from "./MessageBubble";
8	
9	interface ChatProps {
10	  conversationId: string | null;
11	  onReply: (reply: MessageReply) => void;
12	}
13	
14	export function Chat({ conversationId, onReply }: ChatProps) {
15	  const [messages, setMessages] = useState<ChatMessage[]>([]);
16	  const [sending, setSending] = useState(false);
17	  const listRef = useRef<HTMLDivElement>(null);
18	  const seq = useRef(0);
19	
20	  function nextId(prefix: string): string {
21	    seq.current += 1;
22	    return `${prefix}-${seq.current}`;
23	  }
24	
25	  // Mantém a lista rolada até a última mensagem.
26	  useEffect(() => {
27	    const el = listRef.current;
28	    if (el) el.scrollTop = el.scrollHeight;
29	  }, [messages, sending]);
30	
31	  async function handleSend(text: string) {
32	    if (!conversationId || sending) return;
33	    setMessages((prev) => [...prev, { id: nextId("lead"), role: "lead", text }]);
34	    setSending(true);
35	    try {
36	      const reply = await sendMessage(conversationId, text);
37	      setMessages((prev) => [
38	        ...prev,
39	        {
40	          id: reply.message_id || nextId("agent"),
41	          role: "agent",
42	          text: reply.reply,
43	          status: reply.status,
44	          skills_used: reply.skills_used,
45	          rules_applied: reply.rules_applied,
46	          handoff: reply.handoff,
47	        },
48	      ]);
49	      onReply(reply);
50	    } catch (err) {
51	      setMessages((prev) => [
52	        ...prev,
53	        { id: nextId("err"), role: "error", text: `Erro ao enviar: ${describeError(err)}` },
54	      ]);
55	    } finally {
56	      setSending(false);
57	    }
58	  }
59	
60	  return (
